page(s,[('Расписание и помещение',['Учебное расписание перечисляет занятия. Аудитория задаёт место конкретного занятия. Номера помещений здесь обозначаются знакомыми числами.'],[W['emploi-du-temps']['example'],W['salle-cours']['example']]),('Время и место',['Один вопрос запрашивает день и час, другой — место. Ответ должен соответствовать тому, что спрашивается.'],[ex('Quand est le cours ? Où est la salle ?','Когда занятие? Где аудитория?','ка(н) э лё ку́р? у э ла са́ль?')]),('Две строки',['Каждая строка расписания относится к своему предмету. Не соединяйте день одного предмета с временем или аудиторией другого.'],[ex('Le cours est lundi à neuf heures, dans la salle deux.','Занятие в понедельник в девять, в аудитории два.','лё кур э лё(н)ди а нё вёр, да(н) ла саль дё́')])])

