grammar(fill(s,[A],['je-voudrais','gomme','un-article','une-article'],[],'Восстановите показанное название ластика с артиклем.','Je voudrais ','жё вудрэ́',' gomme.','го́м',cards(['un-article','une-article']),1,'Je voudrais une gomme.','жё вудрэ юн го́м.','Сохранено сочетание женского рода.','Название ластика в изученном образце используется с артиклем женского рода.'))
order(s,[A],['je-voudrais','cahier','et','gomme','sil-vous-plait'],[],'Соберите просьбу о тетради и ластике. Начните с вежливой рамки и сохраните этот порядок вещей.',[('Je voudrais','жё вудрэ́'),('un cahier','э(н) кайе́'),('et une gomme,','э юн го́м'),('s’il vous plaît.','силь ву плэ́')],'Je voudrais un cahier et une gomme, s’il vous plaît.','жё вудрэ э(н) кайе э юн гом, силь ву плэ́.','Получилась просьба о двух нужных принадлежностях.','Сначала поставьте рамку, затем тетрадь, ластик и пожалуйста.')
